def _flatten_payload(value: object) -> list[str]:
    """Recursively collect the keys and scalar values of a payload as strings."""
    parts: list[str] = []
    if isinstance(value, dict):
        for key, item in value.items():
            parts.append(str(key))
            parts.extend(_flatten_payload(item))
    elif isinstance(value, (list, tuple, set)):
        for item in value:
            parts.extend(_flatten_payload(item))
    elif value is not None:
        parts.append(str(value))
    return parts


